import re
from collections import OrderedDict


def normalize_method(method):
    """Normalize method to uppercase."""
    return method.upper()


def normalize_permission(permission):
    """Normalize permission to uppercase."""
    return permission.upper()


def is_valid_method(method):
    """Check if method is valid."""
    return method.upper() in ('GET', 'POST', 'PUT', 'DELETE', 'PATCH')


def is_valid_permission(permission):
    """Check if permission is valid."""
    return permission.upper() in ('ALLOW', 'DENY')


def extract_variables(path):
    """
    Extract valid variable patterns from path.
    Returns list of (start_pos, var_name) for valid {name} patterns.
    Invalid patterns (with spaces, etc.) are treated as literal text.
    """
    # Pattern for valid variable: { followed by alphanumeric/underscore/hyphen, then }
    var_pattern = r'\{([a-zA-Z0-9_-]+)\}'
    variables = []
    for match in re.finditer(var_pattern, path):
        variables.append((match.start(), match.group(1)))
    return variables


def normalize_path_for_matching(path):
    """
    Normalize path by replacing all valid {variable_name} with {var}.
    """
    # Replace all valid variable patterns with {var}
    result = re.sub(r'\{[a-zA-Z0-9_-]+\}', '{var}', path)
    return result


def get_path_segments(path):
    """Get non-empty segments from path by splitting on /."""
    segments = [s for s in path.split('/') if s]
    return segments


def path_has_base(path, base):
    """Check if path starts with base (exact prefix match)."""
    if not base:
        return True
    return path.startswith(base)


def is_proper_prefix(normalized_parent, normalized_child):
    """
    Check if normalized_parent is a proper prefix of normalized_child.
    Parent must be strictly shorter and a prefix (child must start with parent + /)
    """
    if not normalized_parent:
        return False
    if normalized_parent == normalized_child:
        return False
    return normalized_child.startswith(normalized_parent + '/')


def parse_input(content):
    """
    Parse input content into sections.
    Returns (endpoints, base_path, exclude_roles, plan_endpoints)
    """
    lines = content.split('\n')

    endpoints = []
    base_path = None
    exclude_roles = set()
    plan_endpoints = []

    state = 'endpoints'  # 'endpoints', 'base_exclude', 'plan'
    endpoints_hard_cutoff = False
    plan_hard_cutoff = False
    in_base_exclude = False

    i = 0
    while i < len(lines):
        line = lines[i]
        stripped = line.strip()

        # Empty line - section separator
        if not stripped:
            if state == 'endpoints' and not endpoints_hard_cutoff:
                state = 'base_exclude'
                in_base_exclude = True
            elif state == 'base_exclude' and not plan_hard_cutoff:
                state = 'plan'
            i += 1
            continue

        # Skip empty lines that might appear within sections (unlikely per spec)
        # But per spec, sections are separated by empty lines

        if state == 'endpoints':
            # Parse endpoint line: path method role permission (4 fields)
            parts = stripped.split()
            if len(parts) != 4:
                # Malformed - hard cutoff
                endpoints_hard_cutoff = True
                # Skip this and remaining lines in endpoints
            else:
                path, method, role, permission = parts
                # Validate: path not empty
                if not path:
                    endpoints_hard_cutoff = True
                # Validate: method valid
                elif not is_valid_method(method):
                    endpoints_hard_cutoff = True
                # Validate: permission valid
                elif not is_valid_permission(permission):
                    endpoints_hard_cutoff = True
                # Validate: role not empty
                elif not role:
